@CrossOrigin
@RestController
@RequestMapping("/DimensionQuery")
public class DimensionQueryRestController extends BaseSpringRestController {
	
	public DimensionQueryRestController( DimensionService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Dimension using a UUID
     * @param		UUID dimensionId
     * @return		Dimension
     */    
    @GetMapping("/load")
    public Dimension load( @RequestParam(required=true) UUID dimensionId ) {
    	Dimension entity = null;

    	try {  
    		entity = service.getDimension( new DimensionFetchOneSummary( dimensionId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Dimension using Id " + dimensionId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Dimension business objects
     * @return		Set<Dimension>
     */
    @GetMapping("/")
    public List<Dimension> loadAll() {                
    	List<Dimension> dimensionList = null;
        
    	try {
            // load the Dimension
            dimensionList = service.getAllDimension();
            
            if ( dimensionList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Dimensions" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Dimensions ", exc );
        	return null;
        }

        return dimensionList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Dimension dimension = null;
    protected DimensionService service = null;
    private static final Logger LOGGER = Logger.getLogger(DimensionQueryRestController.class.getName());
    
}
